(function(){"use strict";function init(){if(document.getElementById("premiumQuickNav"))return;var dock=document.querySelector(".premium-dock");if(dock){document.body.classList.add("premium-dock-ready")}var menu=document.getElementById("menuModalOverlay");var links=menu?Array.from(menu.querySelectorAll('a[href^="#"]')):[];var used=new Set,items=[];links.forEach(function(a){var href=a.getAttribute("href"),id;try{id=decodeURIComponent(href.slice(1))}catch(e){return}if(!id||used.has(id)||!document.getElementById(id))return;var name=(a.textContent||"").replace(/\s+/g," ").trim();if(!name||name.length>52)return;used.add(id);items.push({id:id,name:name})});if(items.length){var wrap=document.createElement("div");wrap.className="premium-quicknav-wrap";wrap.id="premiumQuickNav";var heading=document.createElement("div");heading.className="premium-quicknav-heading";var label=document.createElement("div");label.className="premium-quicknav-label";label.textContent="Rychlý přístup";heading.appendChild(label);var searchButton=document.createElement("button");searchButton.type="button";searchButton.id="premiumSearchQuick";searchButton.textContent="⌕ Vyhledat v celé stránce";searchButton.title="Vyhledat slovo nebo frázi (Ctrl+K)";searchButton.addEventListener("click",function(){var original=document.getElementById("uxSearchBtn");if(original)original.click()});heading.appendChild(searchButton);wrap.appendChild(heading);var nav=document.createElement("nav");nav.className="premium-quicknav";nav.setAttribute("aria-label","Rychlý přístup k sekcím");items.slice(0,16).forEach(function(it){var a=document.createElement("a");a.href="#"+encodeURIComponent(it.id);a.textContent=it.name;nav.appendChild(a)});wrap.appendChild(nav);var main=document.querySelector(".main-wrapper");if(main&&main.parentNode)main.parentNode.insertBefore(wrap,main);else{var hero=document.querySelector(".hero");if(hero)hero.insertAdjacentElement("afterend",wrap)}}var search=document.getElementById("uxSearchBtn");if(search&&dock){search.tabIndex=-1;search.setAttribute("aria-hidden","true")}}if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",init);else init()})();